use verus::prelude::*;

//// Returns the index of a minimal element in the subarray `a[lo..]`.
////
//// # Panics
////
//// Panics if `lo >= a.len()`.
#[requires(lo < a.len())]
#[ensures(|res: usize|
    // result is within the slice
    lo <= res && res < a.len()
    // and for every j in [lo, a.len()), a[res] <= a[j]
    && forall(|j: usize| lo <= j && j < a.len() ==> a[res] <= a[j])
)]
#[decreases(a.len() - lo)]
fn find_min(a: &[i32], lo: usize) -> usize {
    // keep the runtime panic for the old #[should_panic] test
    assert!(lo < a.len(), "starting index out of bounds");

    let mut min_idx = lo;
    for i in (lo + 1)..a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }
    min_idx
}

