    #[test]
    fn test_find_min_basic() {
        let arr = [5, 3, 6, 2, 4];
        assert_eq!(find_min(&arr, 0), 3); // minimal in [5,3,6,2,4] is 2 at index 3
        assert_eq!(find_min(&arr, 1), 3); // minimal in [3,6,2,4] is 2 at index 3
        assert_eq!(find_min(&arr, 2), 3); // minimal in [6,2,4] is 2 at index 3
        assert_eq!(find_min(&arr, 3), 3); // minimal in [2,4] is 2 at index 3
        assert_eq!(find_min(&arr, 4), 4); // minimal in [4] is 4 at index 4
    }

